binders.type:
∀ k ≥ 1,
  have r := a k;
  have m := r.num;
  have n := r.den;
  m > 0 → n > 0 → IsCoprime m ↑n → a (k + 1) = (↑m + 18) / (↑n + 19)

info.goal:
IsGreatest
  {m | ∀ (x y z u : ℤ), x > 0 → y > 0 → z > 0 → u > 0 → x ≥ y → x + y = z + u → 2 * x * y = z * u → m ≤ ↑x / ↑y}
  (3 + 2 * √2)

∃ a,
  have N := ∑ i ∈ Icc 1 n, i.totient;
  (∀ k ∈ Icc 1 n, {i | a i = k}.encard = ↑k.totient) ∧ ∑ i ∈ Icc 1 N, 1 / (a i * a ((i + 1) % N)) = 1

IsLeast
  {x | ∃ a b c d, 0 < a ∧ 0 < b ∧ 0 < c ∧ 0 < d ∧ (a + c) * (b + d) = a * c + b * d ∧ x = a / b + b / c + c / d + d / a}
  8

IsLeast
  {N | ∀ (s : Finset (Fin (2 * n - 1))), #s = N → ∃ a ∈ s, ∃ b ∈ s, a ≠ b ∧ {x | x ∈ univ \ s ∧ x ∈ Ioo a b}.ncard = n}
  (if 3 ∣ 2 * n - 1 then n - 1 else n)

have I1 := n.choose 3;
have I2 := 4 * n.choose 4;
have I3 := 5 * n.choose 5;
have I4 := n.choose 6;
I1 + I2 + I3 + I4 = n.choose 3 + 4 * n.choose 4 + 5 * n.choose 5 + n.choose 6

IsGreatest
  {x | ∃ A B C, A ∈ Ioo 0 π ∧ B ∈ Ioo 0 π ∧ C ∈ Ioo 0 π ∧ A + B + C = π ∧ x = sin (A / 2) * sin (B / 2) * sin (C / 2)}
  (1 / 8)

have V := n + n.choose 4;
have E := (n * (n - 1) + 4 * n.choose 4) / 2;
have F := E - V + 1;
F = (n - 1) * (n - 2) * (n ^ 2 - 3 * n + 12) / 24
